head.script:
//
{
  "@context": "https://schema.org",
  "@type": "WebSite",
  "name": "Organictopia",
  "url": "https://organictopia.blogspot.com/",
  "description": "Where small spaces grow big harvests. Urban Organic Gardening & Micro-Farming Research.",
  "publisher": {
    "@type": "Organization",
    "name": "Organictopia Lab",
    "logo": {
      "@type": "ImageObject",
      "url": "https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop&w=600&q=80"
    }
  }
}
//

head.b:skin:
:root {
  --bg-body: #f8faf7;
  --bg-surface: #ffffff;
  --bg-surface-elevated: #ffffff;
  --bg-surface-subtle: #f1f5ef;
  --border-color: #e2e8df;
  --border-subtle: #edf2eb;

  --brand-primary: #047857;
  --brand-primary-hover: #065f46;
  --brand-primary-light: #ecfdf5;
  --brand-emerald-dark: #064e3b;
  --brand-accent: #10b981;
  --brand-accent-glow: rgba(16, 185, 129, 0.15);
  --brand-orange: #f97316;

  --text-main: #192a24;
  --text-muted: #566860;
  --text-subtle: #84958e;

  --font-body: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'Outfit', sans-serif;

  --shadow-sm: 0 1px 3px rgba(16, 42, 33, 0.05);
  --shadow-md: 0 4px 12px rgba(16, 42, 33, 0.08);
  --shadow-lg: 0 12px 30px rgba(16, 42, 33, 0.12);
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-full: 9999px;
  --transition-base: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

[data-theme="dark"] {
  --bg-body: #0a110f;
  --bg-surface: #101c18;
  --bg-surface-elevated: #162520;
  --bg-surface-subtle: #0d1714;
  --border-color: #1e332c;
  --border-subtle: #14241f;

  --brand-primary: #10b981;
  --brand-primary-hover: #34d399;
  --brand-primary-light: rgba(16, 185, 129, 0.12);
  --brand-emerald-dark: #064e3b;
  --brand-accent: #34d399;
  --brand-accent-glow: rgba(52, 211, 153, 0.2);

  --text-main: #ecf5f1;
  --text-muted: #95aaa0;
  --text-subtle: #62776e;

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 14px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 12px 32px rgba(0, 0, 0, 0.5);
}

/* Reset Blogger Defs */
.quickedit, .widget-item-control, .post-feeds, .feed-links, #navbar-iframe { display: none !important; }
* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font-body);
  background-color: var(--bg-body);
  color: var(--text-main);
  line-height: 1.65;
  transition: background-color 0.3s ease, color 0.3s ease;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Site Header */
header.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(248, 250, 247, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
}
[data-theme="dark"] header.site-header {
  background: rgba(10, 17, 15, 0.92);
}

.nav-wrapper {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
  color: var(--text-main);
}

.brand-badge-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--brand-emerald-dark), var(--brand-accent));
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-size: 1.25rem;
  box-shadow: 0 4px 10px var(--brand-accent-glow);
}

.brand-text .logo-title {
  font-family: var(--font-heading);
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.1;
  color: var(--text-main);
}

.brand-text span {
  font-size: 0.75rem;
  color: var(--brand-primary);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 1.75rem;
  list-style: none;
}

.nav-links a {
  text-decoration: none;
  color: var(--text-muted);
  font-weight: 600;
  font-size: 0.92rem;
  transition: var(--transition-base);
}
.nav-links a:hover { color: var(--brand-primary); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.search-toggle-btn, .theme-toggle-btn {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  color: var(--text-main);
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 1rem;
  transition: var(--transition-base);
}
.search-toggle-btn:hover, .theme-toggle-btn:hover {
  border-color: var(--brand-accent);
  transform: translateY(-1px);
}

.btn-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--brand-primary);
  color: #ffffff !important;
  font-weight: 700;
  font-size: 0.88rem;
  padding: 0.65rem 1.25rem;
  border-radius: var(--radius-full);
  text-decoration: none;
  transition: var(--transition-base);
  box-shadow: 0 4px 14px var(--brand-accent-glow);
  border: none;
  cursor: pointer;
}
.btn-cta:hover {
  background: var(--brand-primary-hover);
  transform: translateY(-2px);
}

/* Expandable Search Bar */
.search-bar-wrap {
  display: none;
  background: var(--bg-surface-elevated);
  border-bottom: 1px solid var(--border-color);
  padding: 1rem 0;
}
.search-bar-wrap.active {
  display: block;
}
.search-form-inner {
  display: flex;
  gap: 0.75rem;
  max-width: 600px;
  margin: 0 auto;
}
.search-input {
  flex: 1;
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-color);
  background: var(--bg-body);
  color: var(--text-main);
  outline: none;
  font-size: 0.95rem;
}
.search-input:focus {
  border-color: var(--brand-primary);
}

/* Hero Banner */
.hero-banner {
  padding: 4rem 0 2.5rem;
  text-align: center;
}
.hero-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 1rem;
  background: var(--brand-primary-light);
  border: 1px solid rgba(16, 185, 129, 0.3);
  color: var(--brand-primary);
  font-weight: 700;
  font-size: 0.8rem;
  border-radius: var(--radius-full);
  margin-bottom: 1.25rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.hero-banner h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4.5vw, 3.2rem);
  font-weight: 800;
  line-height: 1.2;
  color: var(--text-main);
  max-width: 840px;
  margin: 0 auto 1rem;
}
.hero-banner p {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 680px;
  margin: 0 auto;
  line-height: 1.7;
}

/* Interactive Calculator Widget */
.calculator-widget {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2.25rem;
  margin: 1.5rem 0 3.5rem;
  box-shadow: var(--shadow-md);
}
.calc-header-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
  gap: 1rem;
}
.calc-header-row h3 {
  font-family: var(--font-heading);
  font-size: 1.45rem;
  font-weight: 700;
  color: var(--text-main);
}
.calc-grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
}
@media (max-width: 768px) {
  .calc-grid-2 { grid-template-columns: 1fr; }
  .nav-links { display: none; }
}
.calc-slider {
  width: 100%;
  accent-color: var(--brand-primary);
  margin: 0.5rem 0;
}
.calc-select {
  width: 100%;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background: var(--bg-body);
  color: var(--text-main);
  margin-top: 0.4rem;
  font-size: 0.95rem;
}
.calc-output-box {
  background: linear-gradient(135deg, rgba(6, 78, 59, 0.1), rgba(16, 185, 129, 0.05));
  border: 1px solid rgba(16, 185, 129, 0.25);
  border-radius: var(--radius-md);
  padding: 1.75rem;
  text-align: center;
}
[data-theme="dark"] .calc-output-box {
  background: linear-gradient(135deg, rgba(6, 78, 59, 0.35), rgba(16, 185, 129, 0.15));
}
.calc-number {
  font-family: var(--font-heading);
  font-size: 2.75rem;
  font-weight: 800;
  color: var(--text-main);
  line-height: 1;
}

/* Main Layout with Sidebar */
.layout-row {
  display: grid;
  grid-template-columns: 2.5fr 1fr;
  gap: 2.5rem;
  margin-bottom: 4rem;
}
@media (max-width: 900px) {
  .layout-row { grid-template-columns: 1fr; }
}

/* Post Card Stream (Homepage / Archive) */
.blog-posts {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.post-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: var(--transition-base);
}
.post-card:hover {
  border-color: var(--brand-accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.post-thumb {
  height: 260px;
  overflow: hidden;
  background: #11201a;
  position: relative;
}
.post-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
  display: block;
}
.post-card:hover .post-thumb img {
  transform: scale(1.04);
}

.post-card-body {
  padding: 2rem;
}

.post-card-tag {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 0.6rem;
  flex-wrap: wrap;
}
.post-card-tag a {
  background: var(--brand-primary-light);
  color: var(--brand-primary);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.65rem;
  border-radius: var(--radius-full);
  text-decoration: none;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.post-card h2.post-card-title {
  font-family: var(--font-heading);
  font-size: 1.55rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 0.75rem;
}
.post-card h2.post-card-title a {
  color: var(--text-main);
  text-decoration: none;
  transition: var(--transition-base);
}
.post-card h2.post-card-title a:hover {
  color: var(--brand-primary);
}

.post-card-snippet {
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.7;
  margin-bottom: 1.5rem;
}

.post-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--border-subtle);
  padding-top: 1rem;
  font-size: 0.85rem;
  color: var(--text-subtle);
}

.btn-read-more {
  color: var(--brand-primary);
  font-weight: 700;
  text-decoration: none;
  transition: var(--transition-base);
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}
.btn-read-more:hover {
  color: var(--brand-primary-hover);
  transform: translateX(3px);
}

/* Single Post Detail Typography */
.single-post-wrapper {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 3rem 2.5rem;
  color: var(--text-main);
}

.breadcrumbs {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.85rem;
  color: var(--text-subtle);
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}
.breadcrumbs a {
  color: var(--brand-primary);
  text-decoration: none;
  font-weight: 600;
}
.breadcrumbs .sep {
  color: var(--border-color);
}

.single-post-wrapper h1.post-title {
  font-family: var(--font-heading);
  font-size: clamp(1.8rem, 3.5vw, 2.5rem);
  line-height: 1.25;
  margin-bottom: 0.75rem;
  color: var(--text-main);
}

.post-meta-bar {
  display: flex;
  align-items: center;
  gap: 1rem;
  font-size: 0.85rem;
  color: var(--text-subtle);
  margin-bottom: 2rem;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid var(--border-subtle);
  flex-wrap: wrap;
}

.post-body.entry-content {
  font-size: 1.05rem;
  line-height: 1.85;
  color: var(--text-main);
}
.post-body.entry-content h2 {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  color: var(--brand-primary);
  margin: 2.25rem 0 0.85rem;
}
.post-body.entry-content h3 {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  margin: 1.75rem 0 0.5rem;
  color: var(--text-main);
}
.post-body.entry-content p {
  margin-bottom: 1.35rem;
}
.post-body.entry-content ul, .post-body.entry-content ol {
  margin: 1rem 0 1.5rem 1.75rem;
}
.post-body.entry-content li {
  margin-bottom: 0.5rem;
}
.post-body.entry-content img {
  max-width: 100%;
  height: auto;
  border-radius: var(--radius-md);
  margin: 1.75rem 0;
  display: block;
}
.post-body.entry-content table {
  width: 100%;
  border-collapse: collapse;
  margin: 1.75rem 0;
  font-size: 0.95rem;
}
.post-body.entry-content th, .post-body.entry-content td {
  padding: 0.75rem 1rem;
  border: 1px solid var(--border-color);
  text-align: left;
}
.post-body.entry-content th {
  background: var(--bg-surface-subtle);
  color: var(--brand-primary);
}
.post-body.entry-content blockquote {
  border-left: 4px solid var(--brand-primary);
  padding: 0.75rem 1.25rem;
  margin: 1.5rem 0;
  font-style: italic;
  color: var(--text-muted);
  background: var(--bg-surface-subtle);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}

/* Social Share Section */
.post-share-wrap {
  margin-top: 2.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}
.share-buttons {
  display: flex;
  gap: 0.6rem;
}
.btn-share {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  text-decoration: none;
  font-size: 0.95rem;
  transition: var(--transition-base);
}
.btn-share.facebook { background: #1877f2; }
.btn-share.twitter { background: #1da1f2; }
.btn-share.whatsapp { background: #25d366; }
.btn-share:hover { transform: translateY(-2px); opacity: 0.9; }

/* Author Bio Box */
.author-box {
  margin-top: 2.5rem;
  padding: 1.75rem;
  border-radius: var(--radius-md);
  background: var(--bg-surface-subtle);
  border: 1px solid var(--border-color);
  display: flex;
  gap: 1.25rem;
  align-items: center;
}
.author-avatar {
  width: 70px;
  height: 70px;
  border-radius: var(--radius-full);
  object-fit: cover;
  border: 3px solid var(--brand-accent);
}
.author-details h4 {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
}
.author-details p {
  font-size: 0.88rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
  line-height: 1.5;
}

/* Newsletter Subscribe Banner */
.newsletter-section {
  background: linear-gradient(135deg, var(--brand-emerald-dark), #0f2c23);
  color: #ffffff;
  border-radius: var(--radius-lg);
  padding: 3rem 2.5rem;
  margin: 3.5rem 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.newsletter-section h3 {
  font-family: var(--font-heading);
  font-size: 1.85rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}
.newsletter-section p {
  color: #a7f3d0;
  font-size: 1rem;
  max-width: 600px;
  margin: 0 auto 1.5rem;
}
.newsletter-form {
  display: flex;
  gap: 0.75rem;
  max-width: 500px;
  margin: 0 auto;
  flex-wrap: wrap;
}
.newsletter-input {
  flex: 1;
  padding: 0.8rem 1.25rem;
  border-radius: var(--radius-full);
  border: 1px solid rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.1);
  color: #ffffff;
  outline: none;
  font-size: 0.95rem;
}
.newsletter-input::placeholder { color: #a7f3d0; }
.btn-subscribe {
  background: var(--brand-accent);
  color: #064e3b;
  font-weight: 800;
  padding: 0.8rem 1.5rem;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: var(--transition-base);
}
.btn-subscribe:hover { background: #6ee7b7; }

/* Pagination */
.blog-pager {
  display: flex;
  justify-content: space-between;
  margin-top: 2.5rem;
}
.pager-link {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  color: var(--text-main);
  padding: 0.6rem 1.25rem;
  border-radius: var(--radius-full);
  text-decoration: none;
  font-weight: 700;
  font-size: 0.88rem;
  transition: var(--transition-base);
}
.pager-link:hover {
  border-color: var(--brand-primary);
  color: var(--brand-primary);
}

/* Sidebar Widgets */
aside.sidebar {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.sidebar-widget {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.75rem;
}
.sidebar-widget h4.widget-title {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 1rem;
  border-bottom: 2px solid var(--brand-primary-light);
  padding-bottom: 0.5rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.product-callout {
  border: 1px dashed var(--brand-primary);
  border-radius: var(--radius-sm);
  padding: 1.25rem;
  background: var(--brand-primary-light);
  margin-bottom: 1rem;
}
.product-callout strong {
  display: block;
  color: var(--brand-emerald-dark);
  margin-bottom: 0.25rem;
}
[data-theme="dark"] .product-callout strong {
  color: var(--brand-accent);
}

/* Floating Back-to-Top Button */
.fab-scroll-top {
  position: fixed;
  bottom: 25px;
  right: 25px;
  width: 44px;
  height: 44px;
  background: var(--brand-primary);
  color: #ffffff;
  border-radius: var(--radius-full);
  display: none;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: var(--shadow-md);
  z-index: 999;
  border: none;
  font-size: 1.1rem;
  transition: var(--transition-base);
}
.fab-scroll-top.visible { display: flex; }
.fab-scroll-top:hover {
  background: var(--brand-primary-hover);
  transform: translateY(-3px);
}

/* Comments Section */
#comments {
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border-color);
}
#comments h4 {
  font-family: var(--font-heading);
  font-size: 1.35rem;
  margin-bottom: 1.25rem;
}

/* Footer */
footer.site-footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-color);
  padding: 3.5rem 0 2rem;
  margin-top: 5rem;
}
.footer-flex {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1.5rem;
}

body.script:
//
  // Search Bar Toggle
  function toggleSearchBar() {
    var wrap = document.getElementById('searchBarWrap');
    if (wrap) {
      wrap.classList.toggle('active');
      if (wrap.classList.contains('active')) {
        var input = wrap.querySelector('input');
        if (input) input.focus();
      }
    }
  }

  // Scroll to Top visibility
  window.addEventListener('scroll', function() {
    var fab = document.getElementById('fabScrollTop');
    if (fab) {
      if (window.scrollY > 400) {
        fab.classList.add('visible');
      } else {
        fab.classList.remove('visible');
      }
    }
  });

  // Dark Mode Toggle for Blogger
  var toggleBtn = document.getElementById('themeToggleBtn');
  function setBlogTheme(mode) {
    if (mode === 'dark') {
      document.documentElement.setAttribute('data-theme', 'dark');
      if (toggleBtn) toggleBtn.textContent = '☀️';
      localStorage.setItem('organictopia_theme', 'dark');
    } else {
      document.documentElement.removeAttribute('data-theme');
      if (toggleBtn) toggleBtn.textContent = '🌙';
      localStorage.setItem('organictopia_theme', 'light');
    }
  }

  var currentTheme = localStorage.getItem('organictopia_theme') || 
    (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
  setBlogTheme(currentTheme);

  if (toggleBtn) {
    toggleBtn.addEventListener('click', function() {
      var isD = document.documentElement.getAttribute('data-theme') === 'dark';
      setBlogTheme(isD ? 'light' : 'dark');
    });
  }

  // POC Calculator for Blogger (English metrics)
  function runBloggerPocCalc() {
    var slider = document.getElementById('bloggerWaterSlider');
    var display = document.getElementById('bloggerWaterDisplay');
    var sel = document.getElementById('bloggerPhaseSelect');
    var out = document.getElementById('bloggerPocOutput');
    var spoon = document.getElementById('bloggerPocSpoon');

    if (!slider || !out) return;

    var lit = parseInt(slider.value, 10);
    display.textContent = lit + ' Litres';

    var mult = 10;
    if (sel.value === 'gen') mult = 20;
    if (sel.value === 'rec') mult = 5;

    var total = lit * mult;
    out.textContent = total;
    spoon.textContent = '~' + (total / 15).toFixed(1) + ' Tablespoons';
  }

  runBloggerPocCalc();
//
